/* Home Battery native custom panel. No CDN, custom Lovelace cards or build step. */
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,u='',n=1)=>v===null||v===undefined?'—':Number.isFinite(Number(v))?(Math.abs(Number(v))<.5*10**(-n)?0:Number(v)).toLocaleString(undefined,{maximumFractionDigits:n})+u:esc(v);
const condition=v=>String(v||'Unknown').replace(/-/g,' ').replace('partlycloudy','Partly cloudy').replace(/^./,c=>c.toUpperCase());
const historyFactor=(key,unit)=>key==='load'&&unit==='kW'?1000:1;

// Recorder states remain in force until the next event, including explicit gaps.
function historyAt(rows,t){
  let lo=0,hi=rows.length-1,index=-1;
  while(lo<=hi){const mid=(lo+hi)>>1;if(rows[mid].t<=t){index=mid;lo=mid+1;}else hi=mid-1;}
  const sample=rows[index];
  return sample&&Number.isFinite(sample.v)?sample:null;
}

const weatherIcon=v=>({'sunny':'mdi:weather-sunny','clear-night':'mdi:weather-night','partlycloudy':'mdi:weather-partly-cloudy','cloudy':'mdi:weather-cloudy','rainy':'mdi:weather-rainy','pouring':'mdi:weather-pouring','lightning':'mdi:weather-lightning','lightning-rainy':'mdi:weather-lightning-rainy','snowy':'mdi:weather-snowy','fog':'mdi:weather-fog','snowy-rainy':'mdi:weather-snowy-rainy'}[v]||'mdi:weather-cloudy');
function bucketHistory(rows,start,end,count=240){
  const size=(end-start)/count,out=[];let bin=null;
  const flush=()=>{if(bin){out.push({...bin,t:(bin.from+bin.to)/2,v:bin.total/bin.ms});bin=null;}};
  for(let i=1;i<rows.length;i++){
    const a=rows[i-1],b=rows[i];let from=Math.max(start,a.t),to=Math.min(end,b.t);
    if(!Number.isFinite(from)||!Number.isFinite(to)||to<=from)continue;
    if(!Number.isFinite(a.v)){flush();if(out.at(-1)?.v!==null)out.push({t:(from+to)/2,v:null,from,to});continue;}
    while(from<to){
      const j=Math.max(0,Math.min(count-1,Math.floor((from-start)/size))),stop=Math.min(to,start+(j+1)*size),dt=stop-from;
      if(dt<=0)break;
      if(bin&&(bin.index!==j||bin.to!==from))flush();
      if(!bin)bin={index:j,from,to:from,total:0,ms:0,lo:Infinity,hi:-Infinity,first:a.v,last:a.v};
      bin.total+=a.v*dt;bin.ms+=dt;bin.to=stop;bin.last=a.v;bin.lo=Math.min(bin.lo,a.v);bin.hi=Math.max(bin.hi,a.v);from=stop;
    }
  }
  flush();return out;
}
function mergeHistory(recorded,live){
  const cutoff=recorded.at(-1)?.t??-Infinity,tail=(live||[]).filter(r=>r.t>cutoff);
  const rows=[...recorded];let previous=cutoff;
  for(const row of tail){if(Number.isFinite(previous)&&row.t-previous>45000)rows.push({t:previous+.001,v:null});rows.push(row);previous=row.t;}
  return rows;
}

class HomeBatteryPanel extends HTMLElement {
  constructor(){super();this.attachShadow({mode:'open'});this.tab='overview';this.loading=false;this.error='';this.historyHours=24;}
  set hass(value){this._hass=value;if(!this.timer)this.refresh();}
  set panel(value){this._panel=value;this.refresh();}
  connectedCallback(){this.timer=setInterval(()=>this.refresh(),10000);this.refresh();}
  disconnectedCallback(){clearInterval(this.timer);this.timer=null;}
  async refresh(){
    if(!this._hass||!this._panel||this.loading)return;
    this.loading=true;
    try{this.model=await this._hass.callWS({type:'home_battery/panel',entry_id:this._panel.config.entry_id});this.captureLive();await this.history();this.render();}
    catch(e){this.error=e.message||String(e);this.render();}finally{this.loading=false;}
  }
  captureLive(){
    const now=Date.now();this.liveTrends??={};
    for(const [key,field] of Object.entries({load:'load_w',current:'current',spread:'cell_spread'})){
      const value=this.model.data[field];
      this.liveTrends[key]=[...(this.liveTrends[key]||[]).filter(r=>r.t>now-3600000),{t:now,v:Number.isFinite(value)?value:null}];
    }
  }
  async history(){
    if(Date.now()-(this.historyTime||0)<60000)return;
    this.historyTime=Date.now();
    const sources=this.model.history_sources||{current:this.model.sources.current_entity||this.model.entities.current,load:this.model.sources.load_entity,spread:this.model.entities.cell_spread};
    this.trends??={};this.historyErrors??={};
    await Promise.all(Object.entries(sources).map(async([key,entity])=>{
      if(!entity)return;
      try{
        const start=new Date(Date.now()-(this.historyHours||24)*3600000).toISOString();
        const rows=await this._hass.callApi('GET',`history/period/${encodeURIComponent(start)}?filter_entity_id=${encodeURIComponent(entity)}&minimal_response&no_attributes`);
        const factor=historyFactor(key,this._hass.states[entity]?.attributes.unit_of_measurement);
        const points=(rows[0]||[]).map(r=>({t:new Date(r.last_changed||r.last_updated).getTime(),v:['unknown','unavailable'].includes(r.state)?null:Number(r.state)*factor})).filter(r=>Number.isFinite(r.t));
        const live=this._hass.states[entity]?.state;
        points.push({t:Date.now(),v:live&&!['unknown','unavailable'].includes(live)&&Number.isFinite(Number(live))?Number(live)*factor:null});
        this.trends[key]=points;delete this.historyErrors[key];
      }catch{this.historyErrors[key]=true;}
    }));
    this.currentHistory=this.trends.current||[];
    try{
      const id=this.model.entities.recorded_savings_total;
      const rows=await this._hass.callWS({type:'recorder/statistics_during_period',start_time:new Date(Date.now()-30*86400000).toISOString(),statistic_ids:[id],period:'day',types:['change']});
      this.savingsHistory=rows[id]||[];
    }catch{this.savingsHistory=[];}
  }
  currentGraph(){return this.plot('current','Charge / discharge','A','#2dd4bf',1,true);}
  historyRange(){return `<label class="range">History window <select data-history-range aria-label="History window">${[[24,'24 hours'],[168,'7 days'],[720,'30 days']].map(([v,label])=>`<option value="${v}" ${v===(this.historyHours||24)?'selected':''}>${label}</option>`).join('')}</select></label>`;}
  trendGraph(key,title,unit,color,factor=1){return this.plot(key,title,unit,color,factor);}
  savingsGraph(){
    const rows=(this.savingsHistory||[]).filter(r=>Number.isFinite(r.change));
    if(!rows.length)return '<p class="note">Daily savings history will appear after HA records monetary statistics.</p>';
    const max=Math.max(.01,...rows.map(r=>Math.abs(r.change))),width=700/rows.length;
    return `<section class="tile"><h2>Recorded net savings · 30 days</h2><svg role="img" aria-label="Daily estimated net savings bars" viewBox="0 0 800 230" style="width:100%"><line x1="40" y1="110" x2="760" y2="110" stroke="#8aa0b5"/>${rows.map((r,i)=>`<rect x="${45+i*width}" y="${r.change>=0?110-r.change/max*85:110}" width="${Math.max(1,width-3)}" height="${Math.abs(r.change)/max*85}" fill="${r.change>=0?'#2dd4bf':'#fb7185'}"><title>${new Date(r.start).toLocaleDateString()}: ${fmt(r.change,' USD',3)}</title></rect>`).join('')}<text x="40" y="225" fill="currentColor">${new Date(rows[0].start).toLocaleDateString()}</text><text x="680" y="225" fill="currentColor">Today</text></svg></section>`;
  }
  async action(key,domain,service,data={},confirm=false){
    const entity=this.model.entities[key]||key;
    if(confirm&&!window.confirm('Apply this change to your battery system?'))return;
    try{await this._hass.callService(domain,service,{entity_id:entity,...data});this.error='';await this.refresh();}
    catch(e){this.error=e.message||String(e);this.shadowRoot.activeElement?.blur();this.render();}
  }
  transferNotice(d){
    const guard=d.utility_charging_blocked?`<p role="${d.has_bms_alarm?'alert':'status'}" class="note"><strong>Utility charging paused</strong> · ${esc(d.charge_guard_status)}<br><small>${d.high_charge_recovery?'BMS permits recovery discharge; charging stays off.':'Source control is shown separately; BMS protection remains active.'}</small></p>`:'';
    if(d.source_transfer){
      const target=d.source_transfer.value==='SBU'?'battery':'utility';
      return guard+`<p role="status" class="note">Waiting for inverter transfer · ${esc(d.mode)} → ${target}<br><small>The inverter may take about 10 minutes. Actual source is shown above; no commands are being retried.</small></p>`;
    }
    if(d.scheduler_status==='Fault latched')return guard+'<p role="alert" class="note">Automatic control paused · review the command result in Advanced.</p>';
    return guard;
  }
  tile(title,value,caption='',className=''){return `<article class="tile ${className}"><div class="label">${esc(title)}</div><strong>${value}</strong><small>${esc(caption)}</small></article>`;}
  button(key,title){return `<button class="action" data-button="${key}">${esc(title)}</button>`;}
  field(key){
    const id=this.model.entities[key]||key,state=this._hass.states[id];if(!state)return '';
    const attr=state.attributes,name=attr.name||attr.friendly_name?.replace(/^Home Battery /,'')||key,unavailable=['unknown','unavailable'].includes(state.state);
    const label=({backup_hours:'Backup time to keep',minimum_reserve:'Minimum reserve floor',charge_target:'Stop utility charging at SOC',charge_cell_ceiling:'Stop utility charging at cell voltage (0 = disabled)',commissioned:'This meter measures the connected critical-load panel',switching_confirmed:'Grid / battery switching has been verified',automatic_enabled:'Run the schedule automatically'})[key]||name||key;
    if(id.startsWith('select.'))return `<label class="field"><span>${esc(label.replace(/^Home Battery /,''))}</span><select data-select="${key}" ${unavailable?'disabled':''}>${(attr.options||[]).map(v=>`<option value="${esc(v)}" ${v===state.state?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
    if(id.startsWith('number.'))return `<label class="field"><span>${esc(label.replace(/^Home Battery /,''))} <small>${esc(attr.unit_of_measurement||'')}</small></span><input data-number="${key}" type="number" required ${unavailable?'disabled':''} min="${attr.min}" max="${attr.max}" step="${attr.step}" value="${esc(state.state)}"></label>`;
    if(id.startsWith('switch.'))return `<label class="field"><span>${esc(label.replace(/^Home Battery /,''))}</span><input data-switch="${key}" type="checkbox" ${unavailable?'disabled':''} ${state.state==='on'?'checked':''}></label>`;
    return '';
  }
  flow(d){
    const net=Number.isFinite(d.charge_w)&&Number.isFinite(d.discharge_w)?d.discharge_w-d.charge_w:null;
    const battery=d.fresh&&d.mode==='Battery'&&net>5,grid=d.fresh&&d.mode==='Line'&&d.grid_voltage>90;
    const charging=d.fresh&&net!==null&&net< -5,solar=d.fresh&&Number.isFinite(d.inverter_pv_power)&&d.inverter_pv_power>5;
    const node=(cls,title,value,caption,icon)=>`<article class="node ${cls}"><ha-icon icon="${icon}"></ha-icon><span>${title}</span><strong>${value}</strong><small>${caption}</small></article>`;
    const route=(kind,active,path,from,to)=>`<path data-source="${from}" data-target="${to}" class="route ${active?kind+'active':''}" d="${path}" ${active?`marker-end="url(#hb-${kind}-arrow)"`:''}/>`;
    const batteryCaption=!d.fresh?'Waiting for live readings':net===null?'Power reading unavailable':net< -5?'Charging '+fmt(-net,' W DC',0):net>5?'Discharging '+fmt(net,' W DC',0):'Idle';
    const description=!d.fresh?'Waiting for live power readings':battery?'Battery supplying the inverter':grid?'Utility supplying the inverter':solar?'Solar supplying the inverter':'Inverter power flow';
    return `<div class="flow"><svg role="img" aria-label="${description}${charging?'; battery charging':''}" viewBox="0 0 600 270" preserveAspectRatio="none"><defs>${[['grid','#60a5fa'],['bat','#fbbf24'],['charge','#2dd4bf'],['solar','#2dd4bf']].map(([key,color])=>`<marker id="hb-${key}-arrow" viewBox="0 0 12 12" refX="10" refY="6" markerUnits="userSpaceOnUse" markerWidth="13" markerHeight="13" orient="auto"><path d="M0 0L12 6L0 12z" fill="${color}"/></marker>`).join('')}</defs>
      ${route('grid',grid,'M198 55L402 55','utility','inverter')}
      ${charging?route('charge',true,'M510 132Q510 198 402 198','inverter','battery'):route('bat',battery,'M402 198Q510 198 510 132','battery','inverter')}
      ${solar?route('solar',true,'M198 198L198 132Q198 80 402 80','solar','inverter'):''}</svg>
      ${node('grid','Utility',!d.fresh||!Number.isFinite(d.grid_voltage)?'Unknown':d.grid_voltage>90?'Available':'Offline',fmt(d.grid_voltage,' V'),'mdi:transmission-tower')}
      ${node('loads','Inverter',fmt(d.inverter_output_power,' W AC',0),'Measured AC output','mdi:home-lightning-bolt-outline')}
      ${node('battery','Battery',fmt(d.soc,'%',1),batteryCaption,'mdi:home-battery-outline')}
      ${solar?node('solar','Solar',fmt(d.inverter_pv_power,' W DC',0),'Measured generation','mdi:solar-power'):''}
      </div>`;
  }
  overview(d){return `<section class="hero"><h2>${!d.fresh?'Waiting for fresh telemetry':d.mode==='Line'?'Utility is supplying the inverter':d.discharge_w>5?'Battery is supplying the inverter':d.inverter_pv_power>5?'Solar is supplying the inverter':'Inverter is in battery mode'}</h2>${this.flow(d)}<p class="note">${this.model.settings.commissioned?'Connected-panel meter':'Reference meter'}: <b>${esc(this._hass.states[this.model.sources.load_entity]?.attributes.friendly_name||this.model.sources.load_entity)}</b> · <b>${fmt(d.load_w,' W',0)}</b>. ${this.model.settings.commissioned?'This meter drives load planning and recorded savings.':'Scheduling uses this selected meter for reserve and price planning. Savings remain projections until the connected panel meter is commissioned.'} Backup estimates use this selected meter.</p><p class="muted">Blue: utility input · green: charging or solar · amber: battery discharge. Battery DC power includes inverter consumption and differs from AC output.</p></section>${this.anticipatedSchedule(d)}
    <div class="columns"><section><h2>Your backup</h2>${this.tile('Estimated outage runtime',fmt(d.runtime_hours,' h',1),'Based on reported SOC and assumed usable capacity')}${this.tile('Outage reserve',fmt(d.reserve_soc,'%',0),'Energy reserved before price-based battery use')}</section>
    <section><h2>What happens next</h2><article class="tile"><strong>${esc(d.plan)}</strong><p>${esc(d.reason)}</p><span class="pill">${esc(d.scheduler_status)}</span></article><div class="actions">${this.button('use_battery','Use battery now')}${this.button('use_grid','Use grid & charge')}</div></section>
    <section><h2>Weather & money</h2>${this.tile('Weather reserve',esc(d.weather_mode),d.storm?'Storm reserve advised':'Routine outlook')}${this.moneySummary(d)}</section></div>
    <div class="columns">${this.tile('Battery energy in',fmt(d.energy_in??d.integrated_energy_in,' kWh',3),Number.isFinite(d.energy_in)?'BMS bridge · cumulative DC charging':'Manager integration · BMS counter unavailable')}${this.tile('Battery energy out',fmt(d.energy_out??d.integrated_energy_out,' kWh',3),Number.isFinite(d.energy_out)?'BMS bridge · cumulative DC discharge':'Manager integration · BMS counter unavailable')}${this.tile('Battery power',fmt(d.battery_power,' W',0),'Positive: discharging · negative: charging',d.battery_power>=0?'amber':'green')}</div>`;}
  loadCandidates(query=''){
    const q=query.toLowerCase().trim(),owned=new Set([...Object.values(this.model.entities||{}),...(this.model.excluded_load_entities||[]),this.model.sources?.charge_power_entity,this.model.sources?.discharge_power_entity]);
    return Object.entries(this._hass.states).filter(([id,s])=>id.startsWith('sensor.')&&!owned.has(id)&&!id.startsWith('sensor.home_battery_')&&!id.startsWith('sensor.critical_loads_')&&!id.startsWith('sensor.it_closet_battery_')&&!id.startsWith('sensor.daly_bms_')&&['W','kW'].includes(s.attributes.unit_of_measurement)&&(!q||(s.attributes.friendly_name+' '+id).toLowerCase().includes(q))).sort((a,b)=>Number(b[0]===this.model.sources.load_entity)-Number(a[0]===this.model.sources.load_entity)||Number(!['unknown','unavailable'].includes(b[1].state))-Number(!['unknown','unavailable'].includes(a[1].state))||(a[1].attributes.friendly_name||a[0]).localeCompare(b[1].attributes.friendly_name||b[0]));
  }
  loadMatches(query=''){
    const matches=this.loadCandidates(query);
    return matches.slice(0,12).map(([id,s])=>`<button type="button" class="load-match" data-load-choice="${esc(id)}"><b>${esc(s.attributes.friendly_name||id)}</b><span>${fmt(['unknown','unavailable'].includes(s.state)?null:Number(s.state),' '+s.attributes.unit_of_measurement,1)}</span><small>${esc(id)}</small></button>`).join('')+`<small>${matches.length>12?'More matches — type more of the name.':matches.length?'Choose the sensor measuring the loads this battery will power.':'No matching power sensors. Choose W or kW, not energy in kWh.'}</small>`;
  }
  scheduleTime(stamp,zone,day=false){
    return new Intl.DateTimeFormat(undefined,{timeZone:zone||'UTC',...(day?{weekday:'short'}:{}),hour:'numeric',minute:'2-digit'}).format(new Date(stamp*1000));
  }
  anticipatedSchedule(d){
    const p=d.schedule_preview||{},rows=p.segments||[],labels={charge:'Charge battery',battery:'Use battery',utility:'Use utility'},icons={charge:'mdi:battery-charging',battery:'mdi:home-battery',utility:'mdi:transmission-tower'},zone=p.timezone;
    const header=`<div class="schedule-heading"><div><span class="eyebrow">YOUR ENERGY PLAN</span><h2>Next 24 hours</h2></div><span class="state-badge ${p.status==='Estimated'?'good':'preview'}">${esc(p.status||'Preparing preview')}</span></div>`;
    if(!rows.length)return `<section class="schedule-card">${header}<p class="muted">${esc(p.message||'Waiting for the next fresh planning update.')}</p></section>`;
    const duration=p.end-p.start,first=rows[0],next=rows.find(s=>s.action!==first.action),title=s=>`${labels[s.action]} · ${this.scheduleTime(s.start,zone,true)} – ${this.scheduleTime(s.end,zone,true)} · estimated battery ${fmt(s.soc_start,'%',0)} → ${fmt(s.soc_end,'%',0)} · ${s.reason}`,point=v=>`${((v.t-p.start)/duration*1000).toFixed(2)},${(74-v.soc*.6).toFixed(2)}`,reserve=v=>`${((v.t-p.start)/duration*1000).toFixed(2)},${(74-v.reserve*.6).toFixed(2)}`,points=p.points||[];
    return `<section class="schedule-card">${header}<div class="schedule-summary"><b>${labels[first.action]} now</b><span>${next?`${labels[next.action]} around ${this.scheduleTime(next.start,zone,true)}`:'No source change expected at the current load'}</span></div><div class="schedule-meta"><span>${esc(p.basis)}</span><span>${esc(p.profile)}</span><span>Estimated, not fixed</span></div><div class="schedule-scroll" role="region" aria-label="Anticipated schedule timeline; scroll horizontally on small screens" tabindex="0"><div class="schedule-canvas"><div class="schedule-track" aria-label="Expected energy source by time">${rows.map((s,i)=>{const width=(s.end-s.start)/duration*100;return `<button class="schedule-step ${s.action}" style="flex-basis:${width}%" data-schedule-step="${i}" aria-label="${esc(title(s))}" title="${esc(title(s))}">${width>=9?`<ha-icon icon="${icons[s.action]}"></ha-icon><b>${labels[s.action]}</b><small>${esc(s.tariff)}</small>`:''}</button>`;}).join('')}</div><div class="schedule-axis">${[0,4,8,12,16,20,24].map((h,i)=>`<span style="left:${h/24*100}%;transform:translateX(${i===0?0:i===6?-100:-50}%)">${i===0?'Now':this.scheduleTime(p.start+h*3600,zone,i===6)}</span>`).join('')}</div><svg class="schedule-soc" viewBox="0 0 1000 88" preserveAspectRatio="none" role="img" aria-label="Estimated battery percentage and outage reserve over the next 24 hours"><line x1="0" x2="1000" y1="14" y2="14" stroke="currentColor" opacity=".1"/><line x1="0" x2="1000" y1="74" y2="74" stroke="currentColor" opacity=".1"/><polyline points="${points.map(reserve).join(' ')}" fill="none" stroke="#2dd4bf" stroke-dasharray="5 5" stroke-width="1.5" vector-effect="non-scaling-stroke"/><polyline points="${points.map(point).join(' ')}" fill="none" stroke="#c4b5fd" stroke-width="2" vector-effect="non-scaling-stroke"/></svg></div></div><div class="schedule-legend">${Object.entries(labels).map(([key,label])=>`<span><i class="${key}"></i>${label} <b>${fmt(rows.filter(s=>s.action===key).reduce((h,s)=>h+(s.end-s.start)/3600,0),' h',1)}</b></span>`).join('')}</div><div class="schedule-battery"><span><i></i>Estimated battery <b>${fmt(first.soc_start,'%',0)} → ${fmt(rows.at(-1).soc_end,'%',0)}</b></span><span><i></i>Dashed: outage reserve</span></div><p data-schedule-detail class="schedule-detail" role="status">${esc(title(first))}</p><small class="muted">${esc(p.message)} Hover or tap a period for details. On mobile, swipe the timeline.</small><details><summary>About this preview</summary><p>${esc(p.assumptions)} The three-minute charge-recovery check is sampled at fifteen-minute resolution. The live controller rechecks every action.</p></details></section>`;
  }
  bindSchedule(){
    const p=this.model.data.schedule_preview;if(!p)return;
    this.shadowRoot.querySelectorAll('[data-schedule-step]').forEach(e=>{
      const show=()=>{const s=p.segments[Number(e.dataset.scheduleStep)],detail=this.shadowRoot.querySelector('[data-schedule-detail]');if(!s||!detail)return;detail.textContent=`${({charge:'Charge battery',battery:'Use battery',utility:'Use utility'})[s.action]} · ${this.scheduleTime(s.start,p.timezone,true)} – ${this.scheduleTime(s.end,p.timezone,true)} · ${s.tariff} · ${fmt(s.price,' USD/kWh',3)} · estimated battery ${fmt(s.soc_start,'%',0)} → ${fmt(s.soc_end,'%',0)} · ${s.reason}`;};
      e.onpointerenter=show;e.onfocus=show;e.onclick=show;
    });
  }
  learningSummary(compact=false){
    const m=this.model,l=m.learning||{},id=m.sources.load_entity,s=this._hass.states[id],status=l.status||'Waiting for history';
    const planning=Number.isFinite(m.data?.peak_forecast_wh)?'Learned peak planning':'Live-load planning',note=`${m.settings.automatic_enabled?'Automatic scheduling enabled':'Automatic scheduling off'} · ${planning}. Learning does not pause the schedule. Reserve, prices and battery protections still decide when to use battery.`;
    if(compact)return `<section class="tile learning-card"><div class="chart-head"><h2>Your load forecast</h2><span class="state-badge ${status==='Ready'?'good':'preview'}">${esc(status==='Ready'?'Forecast available':status)}</span></div><b>${esc(s?.attributes.friendly_name||id||'Choose a power sensor')}</b><small>${fmt(l.available_days||0,' days',1)} of recorded use · learning from the last ${l.history_days||14} days</small><p>${esc(note)}</p><button data-choose-load>Choose loads & history</button></section>`;
    return `<section class="tile learning-card"><div class="chart-head"><h2>Learning your loads</h2><span class="state-badge ${status==='Ready'?'good':'preview'}">${esc(status==='Ready'?'Forecast available':status)}</span></div><b>${esc(s?.attributes.friendly_name||id||'Choose a power sensor')}</b><p>${fmt(l.available_days||0,' days',1)} of readings found · looking back ${l.history_days||14} days</p><progress max="100" value="${Number(l.coverage_percent)||0}" aria-label="Recorded history coverage"></progress><small>Missing history stays missing. Learning refreshes automatically as more readings arrive.</small>${l.typical_error_w!==null&&l.typical_error_w!==undefined?`<p>Past predictions typically missed by <b>${fmt(l.typical_error_w,' W',0)}</b> across ${l.validation_hours} checked hours.</p>`:'<p class="muted">Prediction checks appear once there is enough earlier history to compare with later readings.</p>'}${Number.isFinite(l.expected_daily_kwh)?`<p>Expected daily use: <b>${fmt(l.expected_daily_kwh,' kWh',2)}</b></p>`:''}<small>${status==='History unavailable'?esc(l.detail):'Uses local Home Assistant history. Learned demand improves savings estimates; peak planning uses it only after sufficient coverage and prediction checks. Otherwise the existing live-load rules remain in use.'}</small><p>${esc(note)}</p><button data-choose-load>Choose loads & history</button></section>`;
  }
  savingsPreference(){
    const current=this.model.settings.planning_goal,id=this.model.entities.planning_goal,state=this._hass.states[id],enabled=state&&!['unknown','unavailable'].includes(state.state);
    const choices=[['Aggressive Savings','Use more available energy','Plan peaks around expected demand without adding prediction-error headroom. Your backup target and minimum reserve still apply.','mdi:lightning-bolt'],['More Savings','Balance savings and backup','Add the typical prediction error to expected peak demand. Keep your requested backup time and reserve.','mdi:scale-balance'],['More Outage Protection','Keep more energy ready','Keep 50% more estimated backup time and add twice the typical prediction error to peak demand. Spare energy can still save money.','mdi:shield-home-outline']];
    return `<section class="preference-section"><h2>Savings preference</h2><p class="muted">Choose how much extra headroom to keep. Every option respects your reserve, charge limits and battery protections.</p><div class="preference-choices">${choices.map(([name,title,detail,icon])=>`<button class="preference-choice" data-profile="${esc(name)}" aria-pressed="${current===name}" ${enabled?'':'disabled'}><ha-icon icon="${icon}"></ha-icon><b>${esc(name)}</b><span>${esc(title)}</span><small>${esc(detail)}</small>${current===name?'<strong>Selected</strong>':''}</button>`).join('')}</div><p class="muted">While learning, all profiles use live load readings to reserve energy for peak hours. Aggressive Savings and More Savings differ once a checked forecast is available. More Outage Protection adds backup headroom immediately. Extra headroom is an estimate, not a runtime guarantee.</p></section>`;
  }
  loadSetup(){
    const m=this.model,id=this.loadDraftEntity||m.sources.load_entity,s=this._hass.states[id];
    return `${this.learningSummary()}<details class="tile load-setup" ${this.loadSetupOpen?'open':''}><summary>What should this battery power?</summary><p>Pick the sensor measuring the appliances or panel you want backed up. Use live power in <b>W or kW</b> — not daily or total energy in kWh.</p><label>Power sensor<input type="search" data-load-search value="${esc(this.loadSearch||'')}" placeholder="Search by sensor name" aria-label="Find a load power sensor" autocomplete="off"></label><div class="load-matches">${this.loadMatches(this.loadSearch||'')}</div><p>Selected: <b data-load-selected>${esc(s?.attributes.friendly_name||id)}</b></p><label>How far back should we learn?<select data-learning-days>${[[7,'7 days — recent changes'],[14,'14 days — recommended'],[30,'30 days — more history'],[90,'90 days — established loads']].map(([v,label])=>`<option value="${v}" ${Number(this.loadDraftDays??m.settings.learning_history_days??14)===v?'selected':''}>${label}</option>`).join('')}</select></label><p class="muted">Home Assistant may have less history than requested. Changing the sensor starts a separate pattern and pauses automatic scheduling for your review. Changing only the history period keeps scheduling enabled.</p><button data-save-load>Save & learn</button><p role="status" class="load-notice">${esc(this.loadSetupNotice||'')}</p></details>`;
  }
  bindLoadSetup(){
    const choose=this.shadowRoot.querySelector('[data-choose-load]');if(choose)choose.onclick=()=>{this.tab='backup';this.loadSetupOpen=true;this.render();this.shadowRoot.querySelector('.load-setup')?.scrollIntoView({block:'start',behavior:'smooth'});};
    const bindMatches=()=>this.shadowRoot.querySelectorAll('[data-load-choice]').forEach(button=>button.onclick=()=>{this.loadDraftEntity=button.dataset.loadChoice;this.shadowRoot.querySelector('[data-load-selected]').textContent=this._hass.states[this.loadDraftEntity]?.attributes.friendly_name||this.loadDraftEntity;});
    const search=this.shadowRoot.querySelector('[data-load-search]');if(search)search.oninput=()=>{this.loadSearch=search.value;this.shadowRoot.querySelector('.load-matches').innerHTML=this.loadMatches(search.value);bindMatches();};
    bindMatches();
    const days=this.shadowRoot.querySelector('[data-learning-days]');if(days)days.onchange=()=>{this.loadDraftDays=Number(days.value);};
    const details=this.shadowRoot.querySelector('.load-setup');if(details)details.ontoggle=()=>{this.loadSetupOpen=details.open;};
    const save=this.shadowRoot.querySelector('[data-save-load]');if(save)save.onclick=async()=>{
      const entity=this.loadDraftEntity||this.model.sources.load_entity,changed=entity!==this.model.sources.load_entity;
      if(changed&&!window.confirm('Use this different load sensor? Automatic scheduling will pause so you can review the new load. Existing history is kept.'))return;
      save.disabled=true;
      try{await this._hass.callWS({type:'home_battery/load_setup',entry_id:this._panel.config.entry_id,load_entity:entity,history_days:Number(this.loadDraftDays??this.model.settings.learning_history_days??14)});this.loadSetupNotice=changed?'Saved. Learning the new loads; review Backup plan before enabling automatic scheduling again.':'Saved. Refreshing the selected history; automatic scheduling is unchanged.';this.loadDraftEntity=null;this.loadDraftDays=null;this.historyTime=0;this.trends={};this.liveTrends={};await this.refresh();}
      catch(e){this.loadSetupNotice=e.message||String(e);}
      finally{const notice=this.shadowRoot.querySelector('.load-notice');if(notice)notice.textContent=this.loadSetupNotice;save.disabled=false;}
    };
  }
  backup(d){return `<div class="section-title"><h2>Backup plan</h2><span class="state-badge ${this.model.settings.commissioned?'good':'preview'}">${this.model.settings.commissioned?'Connected panel':'Reference meter'}</span></div><p class="muted">Keep the outage reserve first. Use the remaining capacity for cheaper electricity.</p>${this.savingsPreference()}${this.loadSetup()}<div class="settings">${['backup_hours','storm_reserve','storm_override','commissioned','switching_confirmed','automatic_enabled'].map(k=>this.field(k)).join('')}</div><details><summary>How the reserve and schedule work</summary><p>The larger of your backup-hour estimate and the minimum percentage floor in Advanced is kept for outages. More Outage Protection multiplies the backup-hour estimate by 1.5 before applying the floor. Storm advice can raise it. Capacity, SOC and efficiency are estimates.</p><p>Scheduling uses the selected meter for planning, whether it is a reference load or the connected panel. Meter commissioning controls savings accounting, not scheduling availability. Automatic scheduling coordinates source preference and charging permission. The controller disables utility charging at your SOC target or optional cell-voltage ceiling without forcing the loads onto battery. Recharge requires five SOC points or 50 mV per cell of recovery, as applicable, and three minutes of clear readings. This supervision requires Home Assistant, MQTT and the bridges; BMS protections remain authoritative. PV charging is not inhibited by this control.</p></details>${this.button('resume_schedule','Resume after manual hold')}`;}

  savings(d){const actual=this.model.settings.commissioned,meta=this.model.attributes.projected_savings_day||{},key=actual?'recorded':'projected',mode=actual?'Recorded':'Projected',unavailable=!actual&&d.projected_savings_day===null;return `<div class="section-title"><h2>${mode} savings</h2><span class="state-badge ${actual?'good':'preview'}"><ha-icon icon="${actual?'mdi:check-decagram':'mdi:flask-outline'}"></ha-icon>${actual?'Connected panel':'Reference-load model'}</span></div><div class="money-periods">${[['day',actual?'Today':'Per day'],['month',actual?'This month':'Per month'],['year',actual?'This year':'Per year']].map(([p,label])=>this.tile(label,fmt(d[key+'_savings_'+p],' USD',2),actual?'Recorded operation':'Projected run rate',d[key+'_savings_'+p]<0?'amber':'')).join('')}</div>${unavailable?`<p class="note">${esc(meta.status||'Waiting for a complete daily load profile and current rates.')}</p>`:''}<section class="tile"><div class="chart-head"><h2>${actual?'What is being counted':'Based on your selected load'}</h2><ha-icon icon="mdi:information-outline"></ha-icon></div>${actual?`<p>Measured charging and battery delivery, valued at the current tariff. Recording began ${this.model.attributes.recorded_savings_total?.since?esc(new Date(this.model.attributes.recorded_savings_total.since).toLocaleString()):'when commissioning is confirmed'}. Projections and earlier test estimates are excluded.</p>`:`<div class="quick-metrics">${this.tile('Daily load',fmt(meta.load_kwh_day,' kWh',2))}${this.tile('Shifted by battery',fmt(meta.shifted_kwh_day,' kWh / day',2))}${this.tile('Grid charge limit',fmt(meta.charge_limit_a,' A DC',0))}${this.tile('Outage reserve',fmt(d.reserve_soc,'%',0))}</div><p class="muted">Models your recorded hourly usage through the source-priority scheduler, using learned weekday/weekend patterns when available. Includes reserve, current charging limit, losses, inverter idle use and charging outside cheap hours. Negative values mean extra cost.</p>`}<details><summary>${actual?'Recorded savings method':'Model assumptions & limits'}</summary><ul>${(actual?['Measured energy with estimated tariff costs; not utility-bill reconciliation']:meta.assumptions||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ul><p class="muted">When the real critical-load meter is selected and commissioned in Backup plan, this view switches to recorded savings automatically. Projections never enter the recorded ledger.</p></details></section><div class="quick-metrics">${this.tile('Price now',fmt(d.current_price===null?null:d.current_price*100,'¢/kWh',2),d.tariff)}${this.tile('Overnight',fmt(d.overnight_price===null?null:d.overnight_price*100,'¢/kWh',2))}</div><details><summary>Electricity prices</summary><div class="settings">${(this.model.settings.price_source==='Manual prices'?['price_source','manual_super_rate','manual_off_rate','manual_peak_rate']:['price_source']).map(k=>this.field(k)).join('')}</div><p class="muted">${esc(d.price_status)}. Current-month prices held constant for projections; year figures are run rates, not future tariff forecasts. Taxes and account-specific adjustments excluded.</p></details>${actual?this.savingsGraph():''}`;}
  health(d){const a=this.model.attributes,status=!d.fresh?'Waiting for live readings':d.healthy?d.alarms:d.alarms==='No alarms'?'Check inverter / bridge':d.alarms;return `<div class="section-title"><h2>Battery health</h2><span class="state-badge ${d.healthy&&!d.has_bms_alarm?'good':'warn'}"><ha-icon icon="${d.healthy&&!d.has_bms_alarm?'mdi:check-circle-outline':'mdi:alert-circle-outline'}"></ha-icon>${esc(status)}</span></div><div class="quick-metrics">${this.tile('Lowest',fmt(d.lowest_cell,' V',3),'Group '+(a.lowest_cell?.positions||[]).join(', '),'amber')}${this.tile('Highest',fmt(d.highest_cell,' V',3),'Group '+(a.highest_cell?.positions||[]).join(', '),'violet')}${this.tile('Difference',fmt(Number.isFinite(d.cell_spread)?d.cell_spread*1000:null,' mV',0))}${this.tile('Temperature',fmt(d.temperature,' °C',1),'Highest BMS probe')}</div>${this.cellChart(d)}<div class="quick-metrics">${this.tile('Charge',fmt(d.soc,'%',0))}${this.tile('Pack voltage',fmt(d.voltage,' V',1))}${this.tile('Current',fmt(d.current,' A',1),'Positive = charging')}${this.tile('Remaining',fmt(d.remaining_ah,' Ah',1),'BMS report')}</div>`;}
  weather(d){const loc=this.model.radar_location||{latitude:39,longitude:-98};return `<div class="section-title"><h2>Weather & readiness</h2><ha-icon icon="mdi:weather-partly-rainy"></ha-icon></div><div class="weather-layout"><div id="weather-context">${this.weatherContext(d)}</div><section class="radar-card"><div class="chart-head"><h2><ha-icon icon="mdi:radar"></ha-icon> Live regional radar</h2><a href="https://radar.weather.gov/" target="_blank" rel="noopener noreferrer">Official radar ↗</a></div><iframe title="Animated regional precipitation radar" src="/home_battery/map/index.html?v=1.2.0-3&lat=${Number(loc.latitude)}&lon=${Number(loc.longitude)}" referrerpolicy="no-referrer" loading="lazy"></iframe><small>Observed precipitation · past hour · play, scrub, zoom or recenter. Regional map; no home marker. RainViewer / OpenStreetMap.</small></section></div><details><summary>Weather reserve controls</summary><div class="settings">${['weather_policy','storm_override','storm_reserve','storm_wind_mph','storm_gust_mph'].map(k=>this.field(k)).join('')}</div><p class="muted">Radar is visual guidance. Official alerts and fresh forecast conditions determine reserve advice. Internet is required for weather, not local inverter controls.</p></details>`;}
  advanced(d){const controls=Object.keys(this.model.entities).filter(k=>this._hass.states[this.model.entities[k]]?.attributes.manual_program!==undefined);return `<h2>System setup & advanced controls</h2><p>Configure source entities under Settings → Devices & services → Home Battery → Configure. Choose live critical-load power in W/kW, and cell sensors in physical group order. AC supply budget is planning only; it does not limit emergency output.</p><div class="settings">${['minimum_reserve','charge_target','charge_cell_ceiling','capacity_kwh','discharge_efficiency','charge_efficiency','overhead_w','reserve_margin','charge_start','charge_end','peak_start','peak_end','charge_cap_a','ac_budget_a','manual_override_minutes'].map(k=>this.field(k)).join('')}</div><h2>Inverter measurements</h2><div class="columns">${this.tile('AC output',fmt(d.inverter_output_power,' W',0),fmt(d.inverter_output_voltage,' V',1)+' · '+fmt(d.inverter_output_frequency,' Hz',1))}${this.tile('Solar input',fmt(d.inverter_pv_power,' W',0),fmt(d.inverter_pv_voltage,' V',1)+' · '+fmt(d.inverter_pv_current,' A',1))}${this.tile('Inverter temperature',fmt(d.inverter_inverter_temperature,' °C',1),'Raw status code: '+d.inverter_status_code)}</div><h2>Inverter controls</h2><p>Ranges come from the bridge. Explanations distinguish configuration readback from physically proven behavior. Unknown codes stay unknown; equalization entries are inactive lead-acid settings.</p><div class="settings">${controls.map(k=>`<div>${this.field(k)}<small>${esc(this._hass.states[this.model.entities[k]]?.attributes.description)}</small></div>`).join('')}</div><div class="note">Bridge: ${esc(d.bridge_status)} · Last command: ${esc(d.command_result)}</div>${this.button('acknowledge_fault','Acknowledge command fault')}<h2>BMS controls</h2><p>These remain owned and verified by your existing BMS integration. They are never changed by the scheduler.</p><div class="settings">${(this.model.sources.bms_control_entities||[]).map(id=>id.startsWith('button.')?`<button data-button="${esc(id)}">${esc(this._hass.states[id]?.attributes.friendly_name||id)}</button>`:this.field(id)).join('')}</div><p><a href="/config/integrations/integration/home_battery">Integration configuration & diagnostics</a></p>`;}
  weatherContext(d){const source=this._hass.states[this.model.sources.weather_entity],a=source?.attributes||{},f=this.model.forecast||[],alerts=this.model.alerts||[],temp=a.temperature_unit||'°C',wind=a.wind_speed_unit||'km/h',icon=weatherIcon(source?.state),policy=this.model.settings.storm_override?'Manual storm reserve':this.model.settings.weather_policy;return `<div class="weather-hero"><ha-icon icon="${icon}"></ha-icon><div><strong>${fmt(a.temperature,' '+temp,0)}</strong><span>${esc(condition(source?.state))}</span></div><div class="weather-policy"><span class="state-badge ${d.storm?'warn':'good'}">${d.storm?'Elevated reserve':'Routine outlook'}</span><small>${esc(policy)}</small><b>${fmt(d.reserve_soc,'%',0)} reserve · ${fmt(d.soc,'%',0)} battery</b></div></div><div class="weather-details">${this.tile('Feels like',fmt(a.apparent_temperature,'°',0))}${this.tile('Wind',fmt(a.wind_speed,' '+wind,0),a.wind_gust_speed===undefined?'':'Gusts '+fmt(a.wind_gust_speed,' '+wind,0))}${this.tile('Humidity',fmt(a.humidity,'%',0))}${this.tile('24h high / low',f.length?fmt(Math.max(...f.map(r=>r.temperature).filter(Number.isFinite)),'°',0)+' / '+fmt(Math.min(...f.map(r=>r.temperature).filter(Number.isFinite)),'°',0):'—')}${this.tile('Rain chance',f.some(r=>Number.isFinite(r.precipitation_probability))?fmt(Math.max(...f.map(r=>r.precipitation_probability||0)),'%',0):'—')}${this.tile('Pressure',fmt(a.pressure,' '+(a.pressure_unit||'hPa'),a.pressure_unit==='inHg'?2:0))}</div><div class="alert-summary ${d.weather_alert_count?'warn':''}"><ha-icon icon="${d.weather_alert_count?'mdi:alert':'mdi:shield-check-outline'}"></ha-icon><b>${d.weather_alert_count===null?'Alerts awaiting update':d.weather_alert_count+' active official alerts'}</b><span>${esc(this.model.sources.nws_alert_zone||'')}</span></div>${alerts.map(r=>`<article class="tile alert"><h3>${esc(r.headline||r.event)}</h3><details><summary>Alert details & instructions</summary><p>${esc(r.description)}</p><p>${esc(r.instruction)}</p><small>Expires ${r.expires?esc(new Date(r.expires).toLocaleString()):'not reported'}</small></details></article>`).join('')}<div class="forecast">${f.map(r=>`<article><small>${new Date(r.datetime).toLocaleTimeString([],{hour:'numeric'})}</small><ha-icon icon="${weatherIcon(r.condition)}"></ha-icon><b>${fmt(r.temperature,'°',0)}</b><small class="rain">${r.precipitation_probability===undefined?'—':fmt(r.precipitation_probability,'%',0)}</small><small>${r.wind_speed===undefined?'':fmt(r.wind_speed,' '+wind,0)}</small></article>`).join('')}</div><small class="muted">Hourly forecast · blue percentage = rain chance · ${esc(a.friendly_name||'No weather provider')}</small>`;}
  moneySummary(d){const actual=this.model.settings.commissioned,mode=actual?'Recorded':'Projected',v=actual?d.recorded_savings_day:d.projected_savings_day;return `<article class="tile money-card ${Number.isFinite(v)&&v<0?'amber':''}"><div class="label"><ha-icon icon="${actual?'mdi:cash-check':'mdi:chart-timeline-variant'}"></ha-icon>${mode} savings${actual?' today':''}</div><strong>${fmt(v,' USD',2)}${actual?'':'<small>/ day</small>'}</strong><small>${actual?'Measured operation · tariff estimate':'Reference load · model, not earnings'}</small></article>`;}
  cellChart(d){
    const cells=d.cells||[],values=cells.filter(Number.isFinite);if(!values.length)return '<p class="note">Waiting for cell readings.</p>';
    const low=Math.min(...values),high=Math.max(...values),limits=d.cell_voltage_limits;
    if(!limits||!Number.isFinite(limits.low)||!Number.isFinite(limits.high)||limits.low>=limits.high)return '<p class="note">Waiting for configured BMS cell-voltage limits. Cell values remain visible above; the bar scale is not guessed.</p>';
    const floor=limits.low,ceiling=limits.high;
    const selected=Number.isInteger(this.selectedCell)?this.selectedCell:cells.indexOf(low),value=cells[selected];
    return `<section class="tile cell-chart"><div class="chart-head"><h2>All ${cells.length} cell groups</h2><span class="muted">Fixed BMS limits</span></div><div class="cell-plot"><div class="cell-axis"><span>${fmt(ceiling,' V',2)}</span><span>${fmt((floor+ceiling)/2,'',2)}</span><span>${fmt(floor,' V',2)}</span></div><div class="cell-bars" style="--groups:${cells.length}">${cells.map((v,i)=>`<button class="cell-column ${selected===i?'selected':''}" data-cell="${i}" aria-label="Group ${i+1}: ${fmt(v,' volts',3)}" title="Group ${i+1}: ${fmt(v,' V',3)}${Number.isFinite(v)&&(v<floor||v>ceiling)?' · Outside BMS limits':''}"><span class="cell-value">${fmt(v,'',3)}</span><span class="cell-track"><span class="cell-fill" style="height:${Number.isFinite(v)?Math.max(0,Math.min(100,(v-floor)/(ceiling-floor)*100)):0}%;background:${v<floor||v>ceiling?'#fb7185':v===low?'#fbbf24':v===high?'#a78bfa':'#2dd4bf'}"></span></span><span>${i+1}</span></button>`).join('')}</div></div><div class="cell-detail"><b>Group ${selected+1} · ${fmt(value,' V',3)}</b><span>${value===low?'Lowest':value===high?'Highest':fmt((value-low)*1000,' mV above lowest',0)}</span></div><small>All bars share ${fmt(floor,'–',2)}${fmt(ceiling,' V',2)} scale from BMS protection settings. Amber = lowest · violet = highest · red = outside limits. Tap a bar for its voltage.</small></section>`;
  }
  plot(key,title,unit,color,factor=1,signed=false){
    let rows=mergeHistory(signed?(this.currentHistory||[]):(this.trends?.[key]||[]),this.liveTrends?.[key]);
    const currentKey={load:'load_w',spread:'cell_spread',current:'current'}[key],live=this.model?.data?.[currentKey];
    if(Number.isFinite(live))rows=[...rows,{t:Date.now(),v:live}];
    rows=rows.map(r=>({...r,v:Number.isFinite(r.v)?r.v*factor:null}));
    const hours=this.historyHours||24,end=Date.now(),start=end-hours*3600000,buckets=bucketHistory(rows,start,end,240),valid=buckets.filter(r=>r.v!==null);
    const current=this.model?(Number.isFinite(live)?live*factor:null):(valid.at(-1)?.v??null);
    const liveColor=signed?(current>0?'#2dd4bf':current<0?'#fbbf24':'#8aa0b5'):color;
    const liveLabel=signed?(current===null?'Live current unavailable':`${current>0?'Charging':current<0?'Discharging':'Idle'} · ${fmt(Math.abs(current),' A',1)}`):fmt(current,' '+unit,1);
    if(valid.length<2)return `<section class="tile chart"><div class="chart-head"><h2>${esc(title)}</h2><b style="color:${liveColor}">${liveLabel}</b></div><p class="muted">Waiting for recorded history.</p></section>`;
    const high=valid.reduce((m,r)=>Math.max(m,r.hi),Math.max(signed?1:unit==='W'?1:10,Number.isFinite(current)?current:0)),low=signed?-Math.max(high,Math.abs(valid.reduce((m,r)=>Math.min(m,r.lo),0)),Number.isFinite(current)?Math.abs(current):0):0,max=signed?-low:high;
    const x=t=>Math.max(0,Math.min(720,(t-start)/(end-start)*720)),y=v=>180-(v-low)/(max-low)*170;
    this.chartData??={};this.chartData[key]={rows,start,end,unit,signed};
    let lines=[],bands=[],run=[];
    const flush=()=>{if(run.length){const first=run[0],last=run.at(-1);run=[{t:first.from,v:first.first,lo:first.first,hi:first.first},...run,{t:last.to,v:last.last,lo:last.last,hi:last.last}];bands.push(`<path d="M${run.map(r=>`${x(r.t)} ${y(r.hi)}`).join('L')}L${[...run].reverse().map(r=>`${x(r.t)} ${y(r.lo)}`).join('L')}Z" fill="${color}" opacity=".10"/>`);if(signed){for(let i=1;i<run.length;i++){let a=run[i-1],b=run[i];if(a.v*b.v<0){const t=a.t+(b.t-a.t)*Math.abs(a.v)/(Math.abs(a.v)+Math.abs(b.v));lines.push(`<path d="M${x(a.t)} ${y(a.v)}L${x(t)} ${y(0)}" stroke="${a.v>=0?'#2dd4bf':'#fbbf24'}"/><path d="M${x(t)} ${y(0)}L${x(b.t)} ${y(b.v)}" stroke="${b.v>=0?'#2dd4bf':'#fbbf24'}"/>`);}else lines.push(`<path d="M${x(a.t)} ${y(a.v)}L${x(b.t)} ${y(b.v)}" stroke="${b.v>=0?'#2dd4bf':'#fbbf24'}"/>`);}}else lines.push(`<path d="M${run.map(r=>`${x(r.t)} ${y(r.v)}`).join('L')}" stroke="${color}"/>`);}run=[];};
    for(const r of buckets){if(r.v===null)flush();else run.push(r);}flush();
    return `<section class="tile chart"><div class="chart-head"><h2>${esc(title)}</h2><b style="color:${liveColor}">${liveLabel}</b></div><div class="plot"><div class="y-axis"><span>${fmt(max,'',signed?1:0)}</span><span>${signed?'0':fmt(max/2,'',0)}</span><span>${fmt(low,'',signed?1:0)}</span></div><svg data-chart="${esc(key)}" tabindex="0" role="img" aria-label="${esc(title)} history in ${unit}. Hover or use left and right arrow keys to inspect recorded values." viewBox="0 0 720 190" preserveAspectRatio="none"><g stroke="currentColor" opacity=".12"><path d="M0 10H720M0 95H720M0 180H720"/></g>${signed?`<path d="M0 ${y(0)}H720" stroke="#8aa0b5" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/>`:''}${bands.join('')}<g fill="none" stroke-width="1.15" stroke-linejoin="round" stroke-linecap="round" style="vector-effect:non-scaling-stroke">${lines.join('')}</g>${Number.isFinite(current)?`<circle aria-label="Live reading" cx="720" cy="${y(current)}" r="2.5" fill="${liveColor}"/>`:''}<path class="chart-cursor" hidden fill="none" stroke="currentColor" stroke-dasharray="3 3"/></svg><output class="chart-tooltip" role="status" hidden></output></div><div class="time-axis"><span>${hours===24?'24 hours':hours/24+' days'} ago</span><span>Now</span></div><div class="chart-legend"><span><i style="background:${color}"></i>${signed?'Green charge · amber discharge':'Time-weighted average'}</span><span>Peak ${fmt(signed?max:high,' '+unit,1)}</span></div>${this.historyErrors?.[key]?'<p class="muted">History refresh unavailable; showing saved history and live samples.</p>':''}<details><summary>About this graph</summary><small>Thin line: bucket average. Faint band: observed range. Actual missing intervals stay gaps; short outages do not erase a whole bucket. History refreshes every minute; live samples update about every ten seconds. Hover, tap or use arrow keys for recorded values and timestamps; these are raw readings, not bucket averages. The endpoint dot is the live reading.</small></details></section>`;
  }
  statusStrip(d){
    const soc=Number.isFinite(d.soc)?Math.max(0,Math.min(100,d.soc)):null,r=Number.isFinite(d.reserve_soc)?d.reserve_soc:null;
    return `<section class="reserve-card"><div class="reserve-head"><span><ha-icon icon="mdi:home-battery"></ha-icon> Battery <b>${fmt(soc,'%',0)}</b></span><span>Outage reserve <b>${fmt(r,'%',0)}</b></span><span class="runtime"><ha-icon icon="mdi:clock-outline"></ha-icon> ${fmt(d.runtime_hours,' h',1)} backup</span></div><div class="reserve-track" role="img" aria-label="Battery ${fmt(soc,'%')} with ${fmt(r,'%')} outage reserve"><div class="soc-fill ${soc!==null&&r!==null&&soc<r?'low':''}" style="width:${soc??0}%"></div><div class="reserve-zone" style="width:${r??0}%"></div><i style="left:${r??0}%"></i></div><div class="reserve-foot"><span>Reserved for outages</span><span>${soc===null||r===null?'Waiting for readings':soc<r?'Below reserve':fmt(soc-r,'%',0)+' above reserve'}</span></div></section>`;
  }
  historyButton(key,label){return `<button data-history="${key}">${esc(label)}</button>`;}
  bindChartHover(){
    this.shadowRoot.querySelectorAll('[data-chart]').forEach(svg=>{
      const chart=this.chartData[svg.dataset.chart],box=svg.closest('.plot'),tip=box.querySelector('.chart-tooltip'),cursor=svg.querySelector('.chart-cursor');
      const show=fraction=>{
        fraction=Math.max(0,Math.min(1,fraction));
        const t=chart.start+fraction*(chart.end-chart.start),sample=historyAt(chart.rows,t);
        cursor.removeAttribute('hidden');cursor.setAttribute('d',`M${fraction*720} 0V190`);
        const when=new Date(t).toLocaleString(),reading=sample?`${fmt(sample.v,' '+chart.unit,3)}${chart.signed?(sample.v>0?' · Charging':sample.v<0?' · Discharging':' · Idle'):''}`:'No recorded data';
        tip.textContent=`${when} · ${reading}${sample?' · Sample '+new Date(sample.t).toLocaleString():''}`;
        tip.hidden=false;tip.style.left=`${Math.max(0,Math.min(box.clientWidth-tip.offsetWidth,45+fraction*svg.clientWidth-tip.offsetWidth/2))}px`;
        svg.dataset.cursor=String(fraction);
      };
      const hide=()=>{cursor.setAttribute('hidden','');tip.hidden=true;};
      svg.onpointermove=e=>{const r=svg.getBoundingClientRect();show((e.clientX-r.left)/r.width);};
      svg.onpointerdown=svg.onpointermove;
      svg.onpointerleave=hide;svg.onblur=hide;
      svg.onfocus=()=>show(Number(svg.dataset.cursor??1));
      svg.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End','Escape'].includes(e.key))return;e.preventDefault();if(e.key==='Escape'){hide();return;}show(e.key==='Home'?0:e.key==='End'?1:Number(svg.dataset.cursor??1)+(e.key==='ArrowLeft'?-1:1)/240);};
    });
  }
  bindControls(){
    this.bindLoadSetup();
    this.bindChartHover();
    this.bindSchedule();
    this.shadowRoot.querySelectorAll('[data-profile]').forEach(e=>e.onclick=()=>this.action('planning_goal','select','select_option',{option:e.dataset.profile},false));
    const range=this.shadowRoot.querySelector('[data-history-range]');if(range)range.onchange=async()=>{this.historyHours=Number(range.value);this.historyTime=0;range.blur();await this.history();this.render();};
    this.shadowRoot.querySelector('#sidebar').onclick=()=>this.dispatchEvent(new CustomEvent('hass-toggle-menu',{bubbles:true,composed:true}));
    this.shadowRoot.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{this.tab=e.dataset.tab;this.render();});
    this.shadowRoot.querySelectorAll('[data-button]').forEach(e=>e.onclick=()=>this.action(e.dataset.button,'button','press',{},e.dataset.button.includes('.')||['use_battery','use_grid','acknowledge_fault'].includes(e.dataset.button)));
    this.shadowRoot.querySelectorAll('[data-select]').forEach(e=>e.onchange=()=>this.action(e.dataset.select,'select','select_option',{option:e.value},!['planning_goal','price_source','weather_policy'].includes(e.dataset.select)));
    this.shadowRoot.querySelectorAll('[data-number]').forEach(e=>e.onchange=()=>{if(e.reportValidity())this.action(e.dataset.number,'number','set_value',{value:Number(e.value)},e.dataset.number.includes('.'));});
    this.shadowRoot.querySelectorAll('[data-switch]').forEach(e=>e.onchange=()=>this.action(e.dataset.switch,'switch',e.checked?'turn_on':'turn_off',{},e.dataset.switch.includes('.')||(e.dataset.switch==='automatic_enabled'&&e.checked)));
    this.shadowRoot.querySelectorAll('[data-history]').forEach(e=>e.onclick=()=>this.dispatchEvent(new CustomEvent('hass-more-info',{detail:{entityId:this.model.entities[e.dataset.history]},bubbles:true,composed:true})));
    this.shadowRoot.querySelectorAll('[data-cell]').forEach(e=>e.onclick=()=>{this.selectedCell=Number(e.dataset.cell);this.render();});
  }
  render(){
    const m=this.model;
    if(['INPUT','SELECT'].includes(this.shadowRoot.activeElement?.tagName))return;
    if(!m){this.shadowRoot.innerHTML=`<p>${esc(this.error||'Loading Home Battery…')}</p>`;return;}
    const d=m.data;
    if(this.tab==='weather'&&this.shadowRoot.querySelector('iframe')){this.shadowRoot.querySelector('#weather-context').innerHTML=this.weatherContext(d);this.shadowRoot.querySelector('header .pill').textContent=d.scheduler_status;this.shadowRoot.querySelector('#transfer-status').innerHTML=this.transferNotice(d);this.bindControls();return;}
    const tabs={overview:'Overview',backup:'Backup plan',savings:'Savings',health:'Battery health',weather:'Weather',advanced:'Advanced'};
    this.shadowRoot.innerHTML=`<style>
    :host{display:block;height:100%;overflow:auto;background:var(--primary-background-color,#0c1726);color:var(--primary-text-color,#e7eef8);font-family:var(--primary-font-family,system-ui)}*{box-sizing:border-box}header{position:sticky;top:0;background:var(--card-background-color,#142436);z-index:2;padding:12px 24px;display:flex;gap:20px;align-items:center;border-bottom:1px solid #334155}header button{padding:8px}.title{font-size:20px;font-weight:750}main{max-width:1400px;margin:auto;padding:24px}nav{display:flex;gap:8px;overflow:auto;padding:8px 0}button,select,input{font:inherit;color:inherit}button,select,input[type=number]{background:var(--card-background-color,#172b40);border:1px solid #43576b;border-radius:12px;padding:12px;cursor:pointer}button:hover{border-color:#2dd4bf}nav button.active{color:#2dd4bf;border-color:#2dd4bf}h1{font-size:clamp(26px,3vw,40px);margin:14px 0 6px}h2{font-size:22px}p{line-height:1.6}small,.muted{color:var(--secondary-text-color,#a8bfd2)}small{display:block}.columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.tile,.hero,.note{background:var(--card-background-color,#15263b);border:1px solid #344558;border-radius:22px;padding:20px;margin:12px 0}.hero{background:linear-gradient(135deg,#173147,#102032);color:#e7eef8}.hero h2{margin-top:0}.tile strong{display:block;font-size:clamp(23px,2.5vw,36px);margin:8px 0;color:#2dd4bf;overflow-wrap:anywhere}.tile.amber strong{color:#fbbf24}.label{font-size:13px;text-transform:uppercase;letter-spacing:.06em}.pill{border:1px solid #507083;border-radius:20px;padding:6px 12px;display:inline-block;font-size:12px}.actions{display:flex;gap:12px}.actions button{flex:1}.flow{height:280px;position:relative;max-width:960px;margin:auto}.flow svg{position:absolute;width:100%;height:100%}.route{fill:none;stroke:#334155;stroke-width:2;vector-effect:non-scaling-stroke}.gridactive{stroke:#60a5fa;stroke-width:4;}.batactive{stroke:#fbbf24;stroke-width:4;}.chargeactive{stroke:#2dd4bf;stroke-width:4;}.node{position:absolute;border:1px solid #526e89;border-radius:18px;background:#142436;width:30%;height:130px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;text-align:center}.node strong{font-size:clamp(22px,3vw,34px)}.node ha-icon{width:24px;height:24px}.node.grid{left:0;top:0;color:#93c5fd}.node.loads{right:0;top:0;color:#ddd6fe}.node.battery{left:35%;top:150px;color:#5eead4}.node small{font-size:12px;color:#a8bfd2}.settings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{display:flex;justify-content:space-between;align-items:center;gap:15px;background:var(--card-background-color,#15263b);padding:16px;border-radius:14px}.field span{flex:1}.field input[type=number]{width:120px}.field select{max-width:50%}.field input[type=checkbox]{width:24px;height:24px;accent-color:#2dd4bf}.cells{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.cells>div{display:flex;gap:12px;align-items:center;padding:12px;background:var(--card-background-color,#15263b);border-radius:12px}.cells meter{flex:1;min-width:0}.forecast{display:flex;overflow:auto;gap:12px;margin-top:20px}.forecast article{min-width:90px;padding:16px;background:var(--card-background-color,#15263b);border-radius:14px;text-align:center}.range{display:flex;gap:12px;align-items:center;margin:20px 0}.trend-summary{display:flex;gap:24px;color:var(--secondary-text-color)}.trend-summary b{color:var(--primary-text-color)}.brand{width:36px;height:36px;object-fit:contain}.weather-top{display:grid;grid-template-columns:1.4fr 1fr;gap:16px}.weather-top .tile strong{font-size:30px}.weather-details{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.weather-details .tile{padding:14px}.weather-details .tile strong{font-size:24px}.alert{border-left:4px solid #fbbf24}.alert p{white-space:pre-line}.error{background:#6b2020;padding:14px;border-radius:12px}a{color:#2dd4bf}@media(max-width:750px){main{padding:16px}.columns,.settings,.cells,.weather-top{grid-template-columns:1fr}.weather-details{grid-template-columns:repeat(2,1fr)}.actions{flex-wrap:wrap}header{padding:10px 16px}.node{width:31%;height:130px}.field{padding:12px}.hero{padding:14px}}
    
    </style><link rel="stylesheet" href="/home_battery/charts.css?v=1.6.1"><header><button id="sidebar" aria-label="Open sidebar">☰</button><img class="brand" src="/home_battery/brand/icon.png" alt="Home Battery logo"><span class="title">Home Battery</span><span class="pill">${esc(d.scheduler_status)}</span></header><main><nav>${Object.entries(tabs).map(([key,name])=>`<button data-tab="${key}" class="${this.tab===key?'active':''}">${({overview:'<ha-icon icon="mdi:view-dashboard-outline"></ha-icon>',backup:'<ha-icon icon="mdi:shield-home-outline"></ha-icon>',savings:'<ha-icon icon="mdi:cash-multiple"></ha-icon>',health:'<ha-icon icon="mdi:battery-heart-outline"></ha-icon>',weather:'<ha-icon icon="mdi:weather-partly-cloudy"></ha-icon>',advanced:'<ha-icon icon="mdi:tune"></ha-icon>'})[key]}${name}</button>`).join('')}</nav>${['overview','backup'].includes(this.tab)?this.statusStrip(d):''}${this.error?`<p role="alert" class="error">${esc(this.error)}</p>`:''}<div id="transfer-status">${this.transferNotice(d)}</div>${this[this.tab](d)}${['overview','health'].includes(this.tab)?this.historyRange():''}${this.tab==='overview'?this.learningSummary(true):''}${this.tab==='overview'?this.trendGraph('load',this.model.settings.commissioned?'Critical-load usage':'Reference-load usage','W','#a78bfa'):''}${this.tab==='health'?this.trendGraph('spread','Cell difference trend','mV','#fbbf24',1000):''}${['overview','health'].includes(this.tab)?this.currentGraph():''}<p class="muted">Home Battery ${esc(m.version)} · measured DC throughput is separate from AC delivery and inferred capacity.</p></main>`;
    this.bindControls();
  }
}
customElements.define('home-battery-panel',HomeBatteryPanel);
